#!/bin/bash
# Uninstall script for Microsoft Build of OpenJDK
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Microsoft Build of OpenJDK..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Microsoft Build of OpenJDK if running..."
pkill -f "Microsoft Build of OpenJDK" 2>/dev/null || true

# Remove $HOME/Library/Preferences/net.java.openjdk.java.plist
echo "Removing $HOME/Library/Preferences/net.java.openjdk.java.plist..."
if [ -d "$HOME/Library/Preferences/net.java.openjdk.java.plist" ]; then
    rm -rf "$HOME/Library/Preferences/net.java.openjdk.java.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/net.java.openjdk.java.plist" ]; then
    rm -f "$HOME/Library/Preferences/net.java.openjdk.java.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/net.java.openjdk.java.savedState
echo "Removing $HOME/Library/Saved Application State/net.java.openjdk.java.savedState..."
if [ -d "$HOME/Library/Saved Application State/net.java.openjdk.java.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/net.java.openjdk.java.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/net.java.openjdk.java.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/net.java.openjdk.java.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
